         "explanation": "같은 높이 창하단에서 더 낮은 각으로 들어온 직선 광선은 수평으로 더 멀리 가서 바닥에 닿아요. 이 조건의 기하 관계를 실내 기온이나 모든 창 조건으로 확대하지 않아요.",
