export function withSeasonContextBankWorkbook(book){
 if(book?.unit!=='c22-s62-u01')return book;let changed=false;
 const revise=rows=>rows?.map(page=>{const patch=bankPagePatches.find(p=>same(p.previous,page));if(!patch)return page;changed=true;const next=clone(page);for(const f of patch.fields){let at=next;for(const k of f.path.slice(0,-1))at=at[k];at[f.path.at(-1)]=clone(f.value);}return next;});
 const pages=revise(book.pages),teacherStudentPages=revise(book.teacherStudentPages);return changed?{...book,pages,...(teacherStudentPages?{teacherStudentPages}:{})}:book;
}
